"use client";

import { AssignedToFilter } from "@/shared/components/AssignedToFilter";
import { DocumentsTable } from "@/features/workflow/components/DocumentsTable";
import { GuidelineCodeMatchDialog, MatchedCodesDialog } from "@/components/GuidelineCodeMatchDialog";
import { MemberSelect } from "@/shared/components/MemberSelect";
import { toMemberSelectRoles } from "@/shared/utils/member-select-roles";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { SearchInput } from "@/components/ui/search-input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import {
  getWorkflowDefinitionFromNodeId,
  processSelectedBacklogItems,
  routeToStep,
} from "@/lib/actions";
import { getMatchedWorkitemsForQueue } from "@/features/workflow/actions/workflow-run-items-actions";
import { REASSIGNMENT_REASONS } from "@/lib/constants";
import { WorkitemList, WorkitemSortParameter } from "@/features/workflow/services/get-member-work-items";
import { WorkflowRunWithIncludes } from "@/shared/types";
import {
  ArrowPathIcon,
  ClockIcon,
  MagnifyingGlassIcon,
  PlayIcon
} from '@heroicons/react/24/outline';
import { DocumentComplexity, JobStatus, UserRole, WorkflowStepType } from "@prisma/client";
import { ArrowLeft, ArrowRight, ClipboardCheck, GitBranch, Pencil } from "lucide-react";
import { useAction } from "next-safe-action/hooks";
import { useRouter, useSearchParams } from "next/navigation";
import { useCallback, useEffect, useMemo, useState, useTransition } from "react";
import { ConfirmationModal } from "@/shared/components/ConfirmationModal";
import { StepSelect } from "./StepSelect";
import { StepDetailsTabsNav } from "./step-details/StepDetailsTabsNav";
import { ProcessConfirmModal } from "./step-details/ProcessConfirmModal";
import { RowAssignDialog } from "./step-details/RowAssignDialog";
import { useStepDetailsBulkActions } from "./step-details/useStepDetailsBulkActions";
import { useStepDetailsStore } from "./step-details/useStepDetailsStore";
import { BulkActionsPanel } from "./step-details/BulkActionsPanel";
import { StepDetailsFiltersBar } from "./step-details/StepDetailsFiltersBar";
import { useMatchedCodesFilter } from "./step-details/useMatchedCodesFilter";
import { StepDetailsTable } from "./step-details/StepDetailsTable";
import { useUIStore } from "@/shared/stores/ui-store";
import { useSessionStore } from "@/shared/stores/session-store";

interface StepDetailsTabsProps {
  stepId: string;
  activeTab: 'backlog' | 'processing' | 'completed' | 'reprocessing';
  workitems: WorkitemList['items'];
  totalCount: number;
  jobStatusFilter: JobStatus[];
  tabCounts: {
    backlog: number;
    processing: number;
    completed: number;
    reprocessing: number;
  };
  stepType: WorkflowStepType;
  stepName: string;
  allowedRoles: string[];
  /** Related documents (shared HCPCS) per document — enables the Related column when set. */
  relatedCountByDocId?: Record<string, number>;
  /** When true, this step is disabled — its documents are read-only (no assign/reprocess/bulk). */
  stepDisabled?: boolean;
  searchParams: {
    search?: string;
    sortBy?: string;
    sortOrder?: string;
    page?: string;
    limit?: string;
    assignedToUserId?: string;
    complexity?: string;
  };
  guidelineChangesByDocId?: Record<string, { added: number; removed: number; updated: number }>;
  policyVersionsByDocId?: Record<
    string,
    {
      currentVersion: string;
      versions: Array<{ label: string; effectiveDate?: string; revisionId: string; status: string }>;
    }
  >;
  prevVersionStatusByDocId?: Record<string, string>;
  /** Set of revision IDs that are waiting for their previous version to complete */
  waitingRevisionIds?: Set<string>;
  /** Optional per-document next version processing status (extract/sourcing UX) */
  nextVersionStatusByDocId?: Record<string, string>;
  /** Optional next revision IDs by document (extract/sourcing UX) */
  nextRevisionIdByDocId?: Record<string, string>;
}

type GuidelineMatchResult = {
  items: WorkitemList['items'];
  totalItems: number;
  matchedCodeCounts: Record<string, number>;
  matchedByTypeCounts: Record<string, { CPT: number; HCPCS: number; ICD_PROC: number }>;
  matchedCodesByType: Record<string, { CPT: string[]; HCPCS: string[]; ICD_PROC: string[] }>;
  matchedDocumentIds: string[];
  totalInputCodes: number;
  inputTotalsByType: { CPT: number; HCPCS: number; ICD_PROC: number };
};

export function StepDetailsTabs({
  stepId,
  activeTab,
  workitems,
  totalCount,
  jobStatusFilter,
  tabCounts,
  stepType,
  stepName,
  allowedRoles,
  relatedCountByDocId,
  stepDisabled = false,
  searchParams,
  guidelineChangesByDocId,
  policyVersionsByDocId,
  prevVersionStatusByDocId,
  waitingRevisionIds,
  nextVersionStatusByDocId,
  nextRevisionIdByDocId,
}: StepDetailsTabsProps) {
  const router = useRouter();
  const urlSearchParams = useSearchParams();
  const [isRefreshing, startRefreshTransition] = useTransition();

  // Consolidated state lives in the step-details Zustand store.
  // Reset on stepId change is wired via useEffect below.
  // Store subscriptions — sub-components (BulkActionsPanel, StepDetailsFiltersBar,
  // useMatchedCodesFilter) subscribe directly, so the parent only subscribes to
  // fields it actually reads/writes in this file.
  const selectedDocuments = useStepDetailsStore((s) => s.selectedDocuments);
  const setSelectedDocuments = useStepDetailsStore((s) => s.setSelectedDocuments);
  const showProcessConfirmModal = useStepDetailsStore((s) => s.showProcessConfirmModal);
  const setShowProcessConfirmModal = useStepDetailsStore((s) => s.setShowProcessConfirmModal);
  const isCodeMatchOpen = useStepDetailsStore((s) => s.isCodeMatchOpen);
  const setIsCodeMatchOpen = useStepDetailsStore((s) => s.setIsCodeMatchOpen);
  const isMatchedCodesOpen = useStepDetailsStore((s) => s.isMatchedCodesOpen);
  const setIsMatchedCodesOpen = useStepDetailsStore((s) => s.setIsMatchedCodesOpen);
  const matchedCodesDocId = useStepDetailsStore((s) => s.matchedCodesDocId);
  const setMatchedCodesDocId = useStepDetailsStore((s) => s.setMatchedCodesDocId);
  const matchedCodesDocName = useStepDetailsStore((s) => s.matchedCodesDocName);
  const setMatchedCodesDocName = useStepDetailsStore((s) => s.setMatchedCodesDocName);
  const matchedCodeCounts = useStepDetailsStore((s) => s.matchedCodeCounts);
  const matchedByTypeCounts = useStepDetailsStore((s) => s.matchedByTypeCounts);
  const matchedCodesByType = useStepDetailsStore((s) => s.matchedCodesByType);
  const matchedTotalCodes = useStepDetailsStore((s) => s.matchedTotalCodes);
  const matchedTotalsByType = useStepDetailsStore((s) => s.matchedTotalsByType);
  const matchedDocumentIds = useStepDetailsStore((s) => s.matchedDocumentIds);
  const matchedItems = useStepDetailsStore((s) => s.matchedItems);
  const matchedTotalItems = useStepDetailsStore((s) => s.matchedTotalItems);
  const matchedPage = useStepDetailsStore((s) => s.matchedPage);
  const clearSignal = useStepDetailsStore((s) => s.clearSignal);
  const lastCodePayload = useStepDetailsStore((s) => s.lastCodePayload);
  const lastUnresolvedCodes = useStepDetailsStore((s) => s.lastUnresolvedCodes);
  const lastSummary = useStepDetailsStore((s) => s.lastSummary);
  const isMatchFilterActive = useStepDetailsStore((s) => s.isMatchFilterActive);
  const moveNote = useStepDetailsStore((s) => s.moveNote);
  const setMoveNote = useStepDetailsStore((s) => s.setMoveNote);
  const reason = useStepDetailsStore((s) => s.reason);
  const setReason = useStepDetailsStore((s) => s.setReason);
  const setView = useStepDetailsStore((s) => s.setView);
  const selectedAssignee = useStepDetailsStore((s) => s.selectedAssignee);
  const setSelectedAssignee = useStepDetailsStore((s) => s.setSelectedAssignee);
  const prevStatusOverrides = useStepDetailsStore((s) => s.prevStatusOverrides);
  const openedFromAssignedCell = useStepDetailsStore((s) => s.openedFromAssignedCell);
  const setOpenedFromAssignedCell = useStepDetailsStore((s) => s.setOpenedFromAssignedCell);
  const assigningRunId = useStepDetailsStore((s) => s.assigningRunId);
  const setAssigningRunId = useStepDetailsStore((s) => s.setAssigningRunId);
  const resetStepDetailsStore = useStepDetailsStore((s) => s.reset);

  const [isPending, startTransition] = useTransition();
  const addNotification = useUIStore((s) => s.addNotification);
  const selectedWFType = useSessionStore((s) => s.selectedWFType);

  // // Server actions
  // const { execute: assignAction, isExecuting: isAssigning } = useAction(assignWorkflowRun); 
  // const { execute: reassignAction, isExecuting: isReassigning } = useAction(reassignWorkflowRuns);
  const { execute: routeToStepAction, isExecuting: isRoutingToStep } = useAction(routeToStep, {
    onError: ({ error }) => {
      let errorMessage = "Failed to route workflow. Please try again.";

      if (error && typeof error === 'object') {
        if ('serverError' in error && typeof error.serverError === 'string') {
          errorMessage = error.serverError;
        } else if ('validationErrors' in error && typeof error.validationErrors === 'object') {
          const validationErrors = error.validationErrors as Record<string, string[]>;
          const errorMessages = Object.values(validationErrors).flat();
          errorMessage = errorMessages.length > 0
            ? errorMessages.join(", ")
            : "Invalid input. Please check your selections.";
        }
      }

      addNotification({
        type: 'error',
        title: 'Routing Failed',
        message: errorMessage,
        duration: 7000,
      });

      // If the run is stale (moved to a newer step), auto-refresh so the
      // user sees the current state without having to manually refresh.
      if (errorMessage.includes('no longer active')) {
        router.refresh();
      }
    }
  })
  const { execute: processAction, isExecuting: isProcessing } = useAction(processSelectedBacklogItems, {
    onError: ({ error }) => {
      let errorMessage = "Failed to process items. Please try again.";

      if (error && typeof error === 'object') {
        if ('serverError' in error && typeof error.serverError === 'string') {
          errorMessage = error.serverError;
        }
      }

      addNotification({
        type: 'error',
        title: 'Processing Failed',
        message: errorMessage,
        duration: 7000,
      });
    }
  });
  const { execute: fetchWorkflow, result: workflowResult } = useAction(getWorkflowDefinitionFromNodeId);

  // Fetch workflow to find starting node
  useEffect(() => {
    if (stepId) {
      fetchWorkflow({ nodeId: stepId });
    }
  }, [fetchWorkflow, stepId]);

  // Reset all step-details state when navigating to a different step.
  useEffect(() => {
    resetStepDetailsStore();
  }, [stepId, resetStepDetailsStore]);

  // Find the starting node (the one with START in prev)
  const startingNodeId = useMemo(() => {
    if (!workflowResult?.data?.success || !workflowResult.data.data) {
      return null;
    }
    const startingNode = workflowResult.data.data.workflowNodes.find(
      node => node.prev?.includes('START')
    );
    return startingNode?.id || null;
  }, [workflowResult]);

  const workflowDefinitionId = workflowResult?.data?.data?.id ?? undefined;

  const { search, sortBy, sortOrder, page, limit, assignedToUserId } = searchParams;
  const currentPage = parseInt(page || "1");
  const pageSize = parseInt(limit || "25");
  // Status filter for AUTONOMOUS backlog tab (controls backlog vs failed documents)
  const statusFilter = urlSearchParams.get("status") as "backlog" | "failed" | "all" | null;

  const sortByParam = urlSearchParams.get("sortBy") || undefined;
  const sortOrderParam = urlSearchParams.get("sortOrder") || undefined;

  const hasAnyFilters =
    !!(
      search ||
      sortByParam ||
      sortOrderParam ||
      searchParams.complexity ||
      assignedToUserId ||
      statusFilter ||
      isMatchFilterActive
    );

  const filteredWorkitems = useMemo(() => {
    if (!isMatchFilterActive) return workitems;
    return matchedItems;
  }, [isMatchFilterActive, matchedItems, workitems]);

  const isExtractStep = stepName.toLowerCase().includes('extract');
  const isDeDuplicationStep = stepName.toLowerCase().replace(/\s+/g, '') === 'deduplication';

  const showGuidelinesSorting = stepType === WorkflowStepType.MANUAL;

  const effectivePrevVersionStatusByDocId = useMemo(() => {
    if (prevVersionStatusByDocId) {
      return {
        ...prevVersionStatusByDocId,
        ...prevStatusOverrides,
      };
    }
    return Object.keys(prevStatusOverrides).length > 0 ? prevStatusOverrides : undefined;
  }, [prevVersionStatusByDocId, prevStatusOverrides]);

  const handleOpenAssignForRun = useCallback(
    (runId: string) => {
      if (stepDisabled) return; // disabled step: no row-level assign
      setSelectedDocuments(new Set([runId]));
      setSelectedAssignee('');
      setAssigningRunId(runId);
      setOpenedFromAssignedCell(true);
    },
    [stepDisabled, setSelectedDocuments, setSelectedAssignee, setAssigningRunId, setOpenedFromAssignedCell],
  );

  const handleCloseRowAssignDialog = useCallback(() => {
    setOpenedFromAssignedCell(false);
    setAssigningRunId(null);
    setSelectedAssignee('');
    setSelectedDocuments(new Set());
  }, []);

  // Assign selected related documents — reuse the exact same dialog + action as the main table.
  const handleOpenAssignForRelated = useCallback(
    (runIds: string[]) => {
      if (stepDisabled || runIds.length === 0) return;
      setSelectedDocuments(new Set(runIds));
      setSelectedAssignee('');
      setAssigningRunId(runIds[0]);
      setOpenedFromAssignedCell(true);
    },
    [stepDisabled, setSelectedDocuments, setSelectedAssignee, setAssigningRunId, setOpenedFromAssignedCell],
  );

  // Pagination calculations
  const totalPages = Math.ceil(totalCount / pageSize);
  const startItem = totalCount > 0 ? ((currentPage - 1) * pageSize) + 1 : 0;
  const endItem = Math.min(currentPage * pageSize, totalCount);
  const hasNextPage = currentPage < totalPages;
  const hasPrevPage = currentPage > 1;
  const paginationInfo = isMatchFilterActive
    ? {
      page: matchedPage,
      limit: pageSize,
      totalCount: matchedTotalItems,
      totalPages: Math.max(1, Math.ceil(matchedTotalItems / pageSize)),
      hasNextPage: matchedPage * pageSize < matchedTotalItems,
      hasPrevPage: matchedPage > 1,
    }
    : {
      page: currentPage,
      limit: pageSize,
      totalCount,
      totalPages,
      hasNextPage,
      hasPrevPage,
    };

  // Roles the step can assign to (from WorkflowStep.allowedRoles). Prefer the full
  // list for MemberSelect so Review can show both reviewers and pharmacists.
  const assignmentRoles = toMemberSelectRoles(allowedRoles);
  // Legacy single-role hint (labels / filters) — first allowed assignable role, else CODER.
  const assignmentRole = assignmentRoles[0] ?? UserRole.CODER;

  const assignmentLabel =
    assignmentRoles.length > 1
      ? "Assign to:"
      : assignmentRole === UserRole.REVIEWER
        ? "Assign to reviewer:"
        : assignmentRole === UserRole.PHARMACIST
          ? "Assign to pharmacist:"
          : assignmentRole === UserRole.ICD_CODER
            ? "Assign to ICD coder:"
            : assignmentRole === UserRole.DEDUPLICATOR
              ? "Assign to deduplicator:"
              : "Assign to:";

  const assignmentPlaceholder =
    assignmentRoles.length > 1
      ? "Select assignee..."
      : assignmentRole === UserRole.REVIEWER
        ? "Select reviewer..."
        : assignmentRole === UserRole.PHARMACIST
          ? "Select pharmacist..."
          : assignmentRole === UserRole.ICD_CODER
            ? "Select ICD coder..."
            : assignmentRole === UserRole.DEDUPLICATOR
              ? "Select deduplicator..."
              : "Select coder...";

  const selectedCount = selectedDocuments.size;
  const displayTotalCount = isMatchFilterActive ? filteredWorkitems.length : totalCount;

  // Users already assigned to the selected runs — disabled in the assign dropdown
  // so a document can't be "reassigned" to whoever already holds it.
  const selectedAssignedUserIds = useMemo(() => {
    const ids = new Set<string>();
    for (const run of filteredWorkitems as WorkflowRunWithIncludes[]) {
      if (selectedDocuments.has(run.id) && run.assignedToRole?.user?.id) {
        ids.add(run.assignedToRole.user.id);
      }
    }
    return Array.from(ids);
  }, [filteredWorkitems, selectedDocuments]);

  const {
    runMatchedQuery,
    handleApplyCodes,
    handleViewMatchedCodes,
    handleClearFilter,
    isMatching,
  } = useMatchedCodesFilter({
    stepId,
    jobStatusFilter,
    pageSize,
    sortBy,
    sortOrder,
    search,
    assignedToUserId,
    complexityParam: searchParams.complexity,
  });


  // URL builder helper - memoized to prevent recreation on every render
  const buildUrl = useCallback((updates: Record<string, string | undefined>) => {
    const params = new URLSearchParams(urlSearchParams.toString());

    Object.entries(updates).forEach(([key, value]) => {
      if (value === undefined || value === '') {
        params.delete(key);
      } else {
        params.set(key, value);
      }
    });

    return `?${params.toString()}`;
  }, [urlSearchParams]);

  // Navigation handlers - memoized for stable references

  const handleSearch = useCallback((query: string) => {
    setSelectedDocuments(new Set());
    startRefreshTransition(() => {
      router.push(buildUrl({ search: query || undefined, page: '1' }));
    });
  }, [buildUrl, router]);

  const handleClearSearch = useCallback(() => {
    setSelectedDocuments(new Set());
    startRefreshTransition(() => {
      router.push(buildUrl({ search: undefined, page: '1' }));
    });
  }, [buildUrl, router]);

  const handlePageChange = useCallback((newPage: number) => {
    setSelectedDocuments(new Set());
    if (isMatchFilterActive && lastCodePayload) {
      runMatchedQuery(lastCodePayload, lastSummary, newPage, lastUnresolvedCodes);
      return;
    }
    startRefreshTransition(() => {
      router.push(buildUrl({ page: newPage.toString() }));
    });
  }, [buildUrl, isMatchFilterActive, lastCodePayload, lastSummary, router, runMatchedQuery]);

  const handlePageSizeChange = useCallback((newPageSize: number) => {
    setSelectedDocuments(new Set());
    if (isMatchFilterActive && lastCodePayload) {
      runMatchedQuery(lastCodePayload, lastSummary, 1, lastUnresolvedCodes);
      return;
    }
    startRefreshTransition(() => {
      router.push(buildUrl({ limit: newPageSize.toString(), page: '1' }));
    });
  }, [buildUrl, isMatchFilterActive, lastCodePayload, lastSummary, router, runMatchedQuery]);

  // Selection handlers - memoized for stable references
  // Must mirror isRowSelectable in DocumentsTable.tsx so the header checkbox
  // doesn't pick up rows that the row-level checkbox correctly disables.
  const handleSelectAll = useCallback(() => {
    if (stepDisabled) return; // disabled step: no selection/work
    const selectableItems = filteredWorkitems.filter(
      (item) =>
        item.jobStatus !== JobStatus.REASSIGNED &&
        item.jobStatus !== JobStatus.REPROCESSING &&
        !(selectedWFType === "UPDATE" && !!item.waitingForRevisionId) &&
        !(selectedWFType === "UPDATE" &&
          (item.previousVersionStatus === "NOT PROCESSED" || item.previousVersionStatus === "IN PROGRESS")) &&
        item.nextVersionStatus !== "IN PROGRESS",
    );
    const isAllSelected = selectableItems.length > 0 && selectableItems.every(item => selectedDocuments.has(item.id));

    if (isAllSelected) {
      setSelectedDocuments(new Set());
    } else {
      setSelectedDocuments(new Set(selectableItems.map(item => item.id)));
    }
  }, [selectedDocuments, filteredWorkitems, selectedWFType, setSelectedDocuments, stepDisabled]);

  const handleSelectDocument = useCallback(
    (runId: string) => {
      if (stepDisabled) return; // disabled step: no selection/work
      const prev = useStepDetailsStore.getState().selectedDocuments;
      const newSelected = new Set(prev);
      if (newSelected.has(runId)) newSelected.delete(runId);
      else newSelected.add(runId);
      setSelectedDocuments(newSelected);
    },
    [setSelectedDocuments, stepDisabled],
  );

  const handleTabChange = useCallback((tab: 'backlog' | 'processing' | 'completed' | 'reprocessing') => {
    setSelectedDocuments(new Set());
    // Clear status filter when switching to processing, completed, or reprocessing tabs
    const updates: Record<string, string | undefined> = { tab, page: '1', search: undefined };
    if (tab !== 'backlog') {
      updates.status = undefined;
    } else {
      updates.assignedToUserId = undefined;
    }
    if (isMatchFilterActive) {
      handleClearFilter();
      startTransition(() => {
        router.push(buildUrl(updates));
      });
    }
    else {
      router.push(buildUrl(updates));
    }
  }, [buildUrl, router, isMatchFilterActive, handleClearFilter]);

  useEffect(() => {
    setView("");
  }, [activeTab]);

  const {
    handleBulkAssignment,
    handleBulkReassignment,
    handleBulkReprocess,
    handleBulkMove,
    handleProcessNow,
    handleProcessNowClick,
  } = useStepDetailsBulkActions({
    selectedDocuments,
    stepId,
    startingNodeId,
    moveNote,
    reason,
    selectedWFType,
    activeTab,
    setSelectedDocuments,
    setReason,
    setMoveNote,
    setView,
    setSelectedAssignee,
    setShowProcessConfirmModal,
    routeToStepAction,
    processAction,
    router,
  });

  const handleViewDocument = useCallback((run: WorkflowRunWithIncludes) => {
    router.push(`/viewer/${run.documentRevision.id}?runId=${run.id}`);
  }, [router]);

  const handleSortChange = useCallback((newSortBy: string) => {
    setSelectedDocuments(new Set());
    // Drop any carried-over sortOrder so a newly picked field starts at its default
    // descending direction — "Newest First" for Created Date. Without this, switching
    // from e.g. Guideline Count ascending would land on Oldest First.
    const updates: Record<string, string | undefined> = {
      sortBy: newSortBy,
      sortOrder: undefined,
      page: '1',
    };
    if (newSortBy !== 'complexity') {
      updates.complexity = undefined;
    }
    startRefreshTransition(() => {
      router.push(buildUrl(updates));
    });
  }, [buildUrl, router]);

  const handleAssignedToChange = useCallback((userId: string | undefined) => {
    setSelectedDocuments(new Set());
    startRefreshTransition(() => {
      router.push(buildUrl({ assignedToUserId: userId, page: '1' }));
    });
  }, [buildUrl, router]);

  const handleClearAllFilters = useCallback(() => {
    setSelectedDocuments(new Set());

    if (isMatchFilterActive) {
      handleClearFilter();
    }

    // Rebuild query params from scratch, preserving only the current tab
    const params = new URLSearchParams();
    const currentTab = urlSearchParams.get("tab");
    if (currentTab) {
      params.set("tab", currentTab);
    }
    params.set("page", "1");

    const target = `?${params.toString()}`;
    startRefreshTransition(() => {
      router.push(target);
      router.refresh();
    });
  }, [handleClearFilter, isMatchFilterActive, router, urlSearchParams]);

  const getPageNumbers = (): number[] => {
    const pages: number[] = [];
    const maxVisiblePages = 5;

    if (totalPages <= maxVisiblePages) {
      for (let i = 1; i <= totalPages; i++) {
        pages.push(i);
      }
    } else {
      const start = Math.max(1, currentPage - 2);
      const end = Math.min(totalPages, start + maxVisiblePages - 1);
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
    }

    return pages;
  };

  const pageNumbers = getPageNumbers();

  return (
    <>
      <div className="relative">
        <div className="sticky top-0 z-10 bg-white pb-4">
          <div>
            <StepDetailsTabsNav
              activeTab={activeTab}
              tabCounts={tabCounts}
              onTabChange={handleTabChange}
            />
          </div>
        </div>

        {/* Table container with filters and table */}
        <div className="rounded-xl border border-gray-200 bg-white overflow-hidden flex flex-col flex-1 min-h-0">
          <StepDetailsFiltersBar
            search={search}
            onSearch={handleSearch}
            onClearSearch={handleClearSearch}
            displayTotalCount={displayTotalCount}
            assignedToUserId={assignedToUserId}
            hasAnyFilters={hasAnyFilters}
            onClearAllFilters={handleClearAllFilters}
            isExtractStep={isExtractStep}
            activeTab={activeTab}
            stepType={stepType}
            allowedRoles={allowedRoles}
            assignmentRole={assignmentRole}
            assignmentRoles={assignmentRoles}
            showGuidelinesSorting={showGuidelinesSorting}
            sortByParam={sortByParam}
            sortOrderParam={sortOrderParam}
            currentComplexity={urlSearchParams.get("complexity")}
            onSortChange={handleSortChange}
            onSortOrderChange={(value) => {
              setSelectedDocuments(new Set());
              router.push(buildUrl({ page: "1", sortOrder: value }));
            }}
            onComplexityChange={(value) => {
              setSelectedDocuments(new Set());
              router.push(
                buildUrl({ page: "1", complexity: value === "all" ? undefined : value }),
              );
            }}
            onAssignedToChange={handleAssignedToChange}
            onClearCodeMatch={handleClearFilter}
            selectedCount={selectedCount}
            onProcessNowClick={handleProcessNowClick}
            isRoutingToStep={isRoutingToStep}
            isProcessing={isProcessing}
            bulkActionsPanel={
              <BulkActionsPanel
                visible={!stepDisabled && selectedCount > 0 && stepType !== "AUTONOMOUS"}
                activeTab={activeTab}
                stepId={stepId}
                allowedRoles={allowedRoles}
                workflowDefinitionId={workflowDefinitionId}
                startingNodeId={startingNodeId}
                isRoutingToStep={isRoutingToStep}
                isProcessing={isProcessing}
                assignmentRole={assignmentRole}
                assignmentRoles={assignmentRoles}
                assignmentPlaceholder={assignmentPlaceholder}
                disabledUserIds={selectedAssignedUserIds}
                onBulkMove={handleBulkMove}
                onBulkAssignment={handleBulkAssignment}
                onBulkReassignment={handleBulkReassignment}
              />
            }
          />

          <StepDetailsTable
            isPending={isPending}
            isRefreshing={isRefreshing}
            isRoutingToStep={isRoutingToStep}
            isProcessing={isProcessing}
            displayTotalCount={displayTotalCount}
            search={search}
            activeTab={activeTab}
            isMatchFilterActive={isMatchFilterActive}
            runs={filteredWorkitems}
            pagination={paginationInfo}
            stepType={stepType}
            selectedDocuments={selectedDocuments}
            allowedRoles={allowedRoles}
            isDeDuplicationStep={isDeDuplicationStep}
            relatedCountByDocId={relatedCountByDocId}
            nodeId={stepId}
            onAssignRuns={handleOpenAssignForRelated}
            stepDisabled={stepDisabled}
            onPageChange={handlePageChange}
            onPageSizeChange={handlePageSizeChange}
            onSelectAll={handleSelectAll}
            onSelectDocument={handleSelectDocument}
            onViewDocument={handleViewDocument}
            onOpenAssignForRun={handleOpenAssignForRun}
            onViewMatchedCodes={handleViewMatchedCodes}
            onClearSearch={handleClearSearch}
            guidelineChangesByDocId={guidelineChangesByDocId}
            policyVersionsByDocId={policyVersionsByDocId}
            prevVersionStatusByDocId={prevVersionStatusByDocId}
            matchedCodeCounts={matchedCodeCounts}
            matchedTotalCodes={matchedTotalCodes}
            matchedByTypeCounts={matchedByTypeCounts}
            matchedTotalsByType={matchedTotalsByType}
          />
        </div>
      </div>

      <GuidelineCodeMatchDialog
        open={isCodeMatchOpen}
        onOpenChange={setIsCodeMatchOpen}
        onApply={handleApplyCodes}
        onClearFilter={handleClearFilter}
        clearSignal={clearSignal}
        isFilterActive={isMatchFilterActive}
        isApplying={isMatching}
      />
      <MatchedCodesDialog
        open={isMatchedCodesOpen}
        onOpenChange={(open) => {
          setIsMatchedCodesOpen(open);
          if (!open) {
            setMatchedCodesDocId(null);
            setMatchedCodesDocName("");
          }
        }}
        documentName={matchedCodesDocName}
        matchedCodes={matchedCodesDocId ? matchedCodesByType[matchedCodesDocId] : undefined}
      />

      <RowAssignDialog
        open={openedFromAssignedCell}
        onClose={handleCloseRowAssignDialog}
        run={
          assigningRunId
            ? (filteredWorkitems as WorkflowRunWithIncludes[]).find((r) => r.id === assigningRunId)
            : undefined
        }
        assignmentLabel={assignmentLabel}
        assignmentRole={assignmentRole}
        assignmentRoles={assignmentRoles}
        assignmentPlaceholder={assignmentPlaceholder}
        selectedAssignee={selectedAssignee}
        onAssigneeChange={setSelectedAssignee}
        workflowDefinitionId={workflowDefinitionId}
        isRoutingToStep={isRoutingToStep}
        onAssign={(id) => handleBulkAssignment(id)}
      />

      <ProcessConfirmModal
        isOpen={showProcessConfirmModal}
        selectedCount={selectedDocuments.size}
        isProcessing={isProcessing}
        onClose={() => setShowProcessConfirmModal(false)}
        onConfirm={() => handleBulkReprocess()}
      />
    </>
  );
}
